'use strict';

/**
* BLAS level 2 routine to perform one of the matrix-vector operations `x = A*x` or `x = A^T*x`, where `x` is an `N` element ndarray and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @module @stdlib/blas/base/ndarray/dtrmv
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
* var dtrmv = require( '@stdlib/blas/base/ndarray/dtrmv' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float64', new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 1.0, 2.0, 3.0, 2.0, 1.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
*
* var out = dtrmv( [ x, A ] );
* // returns <ndarray>[ 14.0, 8.0, 3.0 ]
*
* var bool = ( out === x );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
